  wd:Q742833 ?p ?o .
  FILTER(STRSTARTS(STR(?p), "http://www.wikidata.org/prop/direct/") &&
        (?p = <http://www.wikidata.org/prop/direct/P31> ||
         ?p = <http://www.wikidata.org/prop/direct/P279>))
  OPTIONAL { ?o rdfs:label ?ol . FILTER(LANG(?ol) = "en") }
}

